/**
 * The server builds design objects too (backend/apps/designs/doc/builders.py, used by the MCP server). This test
 * loads every object it builds through the real engine: each must be recognised as the intended kind, survive a
 * load and save unchanged and, where the editor has a factory for the same object, come out exactly like the
 * editor's own; effects and curves must also be drawn. The fixture is generated by
 * `python -m apps.designs.doc.contract` and checked by a backend test.
 */
import { type FabricObject, Group, StaticCanvas } from 'fabric'
import { installImageStub } from '../test/imageStub'
import type { DocObject } from '@/types/document'
import cases from './fixtures/backend-builders.json'
import { asDory } from './objects/dory'
import {
  createEllipse,
  createImage,
  createLine,
  createPathShape,
  createPolygon,
  createRect,
  createStar,
  createTextbox,
  createTriangle,
  type LineOptions,
  type TextOptions,
} from './objects/factories'
import { kindOfDoc } from './objects/kinds'
import { type LoadContext, deserializeObjects, serializeObjects } from './serialization'

interface Factory {
  fn: string
  opts?: Record<string, unknown>
  size?: number
  radius?: number
  sides?: number
  points?: number
  innerRatio?: number
  src?: string
  fit?: number
  shapeId?: string
  /** Properties set on the object after the factory made it. */
  set?: Record<string, unknown>
  children?: Factory[]
}

interface Case {
  name: string
  kind: string
  factory?: Factory
  object: DocObject
  ignore?: string[]
  /** Live properties the editor must have set when it loaded the object (`true`: any value). */
  expect?: Record<string, unknown>
  /** The children the backend places on the page when it ungroups `object`. */
  ungrouped?: DocObject[]
}

const ctx: LoadContext = { resolveSrc: async (s) => s, ensureFonts: async () => undefined }
const page = { width: 800, height: 600 }
const at = { x: 400, y: 300 }

async function fromFactory(f: Factory): Promise<FabricObject> {
  const obj = await make(f)
  if (f.set) {
    obj.set(f.set)
    obj.setCoords()
  }
  return obj
}

async function make(f: Factory): Promise<FabricObject> {
  switch (f.fn) {
    case 'createGroup':
      return new Group(await Promise.all((f.children ?? []).map(fromFactory)))
    case 'createTextbox':
      return createTextbox(page, at, f.opts as TextOptions)
    case 'createRect':
      return createRect(at, f.size as number, f.radius)
    case 'createEllipse':
      return createEllipse(at, f.size as number)
    case 'createTriangle':
      return createTriangle(at, f.size as number)
    case 'createPolygon':
      return createPolygon(at, f.size as number, f.sides)
    case 'createStar':
      return createStar(at, f.size as number, f.points, f.innerRatio)
    case 'createPathShape':
      return createPathShape(f.shapeId as string, at, f.size as number) as FabricObject
    case 'createLine':
      return createLine(at, f.opts as unknown as LineOptions)
    case 'createImage':
      return createImage({ src: f.src as string, url: f.src as string }, at, { width: f.fit as number, height: f.fit as number })
    default:
      throw new Error(`unknown factory ${f.fn}`)
  }
}

function save(objects: FabricObject[]): DocObject[] {
  const canvas = new StaticCanvas(document.createElement('canvas'), { ...page, renderOnAddRemove: false })
  canvas.add(...objects)
  const out = serializeObjects(canvas)
  canvas.dispose()
  return out
}

/** Equal as JSON, numbers within 0.001 (Fabric rounds to three decimals, Python and JS round halves alike). */
function close(a: unknown, b: unknown): boolean {
  if (typeof a === 'number' && typeof b === 'number') return Math.abs(a - b) < 1e-3
  if (Array.isArray(a) && Array.isArray(b)) return a.length === b.length && a.every((x, i) => close(x, b[i]))
  if (a && b && typeof a === 'object' && typeof b === 'object') {
    const ka = Object.keys(a)
    const kb = Object.keys(b)
    return ka.length === kb.length && ka.every((k) => close((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k]))
  }
  return a === b
}

/** Every key `want` has comes back in `got` (recursively; arrays element by element), numbers within 0.001. */
function covers(got: unknown, want: unknown): boolean {
  if (Array.isArray(want)) return Array.isArray(got) && got.length === want.length && want.every((w, i) => covers(got[i], w))
  if (want && typeof want === 'object') {
    if (!got || typeof got !== 'object') return false
    return Object.entries(want).every(([k, w]) => covers((got as Record<string, unknown>)[k], w))
  }
  return close(got, want)
}

function without(object: DocObject, keys: string[]): Record<string, unknown> {
  const copy: Record<string, unknown> = { ...object }
  for (const key of keys) delete copy[key]
  // A group's children carry ids of their own, which differ between the two makers.
  if (Array.isArray(copy.objects)) copy.objects = (copy.objects as DocObject[]).map((child) => without(child, ['id']))
  return copy
}

describe('objects built by the backend', () => {
  let restoreImages: () => void
  beforeAll(() => {
    restoreImages = installImageStub()
  })
  afterAll(() => restoreImages())

  it.each(cases as Case[])('$name', async (c) => {
    expect(kindOfDoc(c.object)).toBe(c.kind)
    const [live] = await deserializeObjects([c.object], ctx)
    expect(asDory(live).rawDoc).toBeUndefined() // not the stand-in for an object that failed to load
    for (const [key, want] of Object.entries(c.expect ?? {})) {
      const got = (live as unknown as Record<string, unknown>)[key]
      if (want === true) expect(got, key).toBeTruthy()
      else expect(got, key).toBe(want)
    }
    const [saved] = save([live])

    // The editor measures text itself; the backend's height is an estimate, except when shrink-to-fit fixes the box height.
    const hasFit = Boolean(c.object.fit)
    const skip = ['id', ...(c.kind === 'text' && !hasFit ? ['height'] : []), ...(hasFit ? ['fitFontSize'] : []), ...(c.ignore ?? [])]
    for (const [key, value] of Object.entries(without(c.object, skip))) {
      expect({ key, value: saved[key] }).toSatisfy(() => covers(saved[key], value))
    }
    if (hasFit) {
      expect(Math.abs(Number(saved.fitFontSize) - Number(c.object.fitFontSize))).toBeLessThanOrEqual(1)
      expect((live as unknown as { fontSize: number }).fontSize).toBeCloseTo(Number(saved.fitFontSize), 3)
    }

    if (c.ungrouped) {
      const children = (live as Group).removeAll()
      const placed = save(children)
      expect(placed.length).toBe(c.ungrouped.length)
      c.ungrouped.forEach((want, i) => {
        for (const key of ['left', 'top', 'angle', 'scaleX', 'scaleY']) {
          const [got, value] = [placed[i][key], want[key]]
          expect({ child: i, key, got, value }).toSatisfy(() => close(got, value))
        }
      })
    }

    if (c.factory) {
      const [own] = save([await fromFactory(c.factory)])
      const mine = without(saved, skip)
      const theirs = without(own, skip)
      expect(close(mine, theirs), JSON.stringify({ mine, theirs })).toBe(true)
    }
  })
})
